edits.replacement:
#root #pausebox #abandonbtn, #root #pausebox #arcendbtn, #root #pausebox #charselbtn{ margin-top:var(--sp-3); }
/* v28.xx (cw-pausetidy) critic c-31 round 2 (pause 3, 25/42/49): the card was 780 wide round a 560 column, the HUD still ghosted through at 97 percent, the way out was not shown, and the leave buttons were the same grey as Feedback. Now: card 640 wide on a keyboard (a pad keeps its legend width), scrim 99 percent, an Esc hint under the buttons, leave buttons in --danger */
body:not(.padon) #root #pausebox::before{ width:min(calc(var(--menu-w) + var(--sp-5) + var(--sp-4)),calc(100% - var(--sp-4))) !important; }
#root #pausebox{ background:color-mix(in srgb,var(--ui-void) 99%,transparent); }
#root #pausebox::after{ content:'Esc  Resume'; font:600 var(--fs-label)/1 var(--f-cond); letter-spacing:var(--track); color:var(--tx-2); margin-top:var(--sp-1); }
body.padon #root #pausebox::after, #root #pausebox.asking::after{ display:none; }
#root #pausebox #abandonbtn, #root #pausebox #arcendbtn, #root #pausebox #charselbtn{ color:var(--danger) !important; border-color:var(--danger) !important; }

check:
{v:'VER',what:'the pause card is 640 wide on a keyboard with an Esc hint, the scrim is 99 percent, and the leave buttons are danger red',
 run:function(){
   var pb=document.getElementById('pausebox'), bad=[], cs, mm, a, s, padWas, ids=['abandonbtn','arcendbtn','charselbtn'], i, b, w, h;
   if(!pb) return 'SKIP: no pause box here';
   padWas=document.body.classList.contains('padon'); document.body.classList.remove('padon');
   try{
     cs=getComputedStyle(pb).backgroundColor; mm=/[\/,]\s*([0-9.]+)\s*\)\s*$/.exec(cs); a=/^rgb\(/.test(cs)?1:(mm?parseFloat(mm[1]):(/^color\(/.test(cs)?1:0));
     if(!(a>=0.985)) bad.push('the pause scrim is '+cs+', the HUD still ghosts through');
     w=getComputedStyle(pb,'::before').width; if(!/\b640px/.test(w)) bad.push('the pause card is '+w+' wide, not 640px');
     h=getComputedStyle(pb,'::after').content; if(!/Esc/.test(h)) bad.push('no Esc hint under the buttons ('+h+')');
     for(i=0;i<ids.length;i++){ b=document.getElementById(ids[i]); if(!b) continue; s=getComputedStyle(b).color; if(s!=='rgb(229, 72, 47)') bad.push(ids[i]+' text is '+s+', not danger red'); }
     document.body.classList.add('padon');
     w=getComputedStyle(pb,'::before').width; if(/\b640px/.test(w)) bad.push('a pad card lost its legend width');
   } finally { document.body.classList.toggle('padon',padWas); }
   return bad.length?bad.join('; '):null; }},
